import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

sdpa_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V);
"""

sdpa_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <c10/cuda/CUDAStream.h>
#include <mma.h>
using namespace nvcuda;
// Specialized tensor-core SDPA for the benchmark shape S=256, D=1024, fp16.
// One CTA computes 16 query rows for one (batch, head):
//   S_tile[16,256] = Q_tile[16,1024] K^T[1024,256] via WMMA over K tiles.
//   P = softmax(S_tile * scale) staged in shared as fp16.
//   O_tile[16,1024] = P[16,256] V[256,1024] via WMMA over S tiles.
constexpr int BM = 16;
constexpr int BQ = 256;
constexpr int BD = 1024;
constexpr int NWARPS = 8;
constexpr int KLD = 24;                 // padded row stride (halfs) for staged K slabs
constexpr int KSTAGE = 128 * KLD;       // one staged slab: 128 keys x 16 depth (padded)
constexpr int LDS = BQ + 8;             // padded sS (float) / sP (half) row stride: kills WMMA bank conflicts
constexpr int VLD = 512 + 8;            // padded staged-V row stride (halfs)
constexpr int VSTAGE = 16 * VLD;        // one staged V slab: 16 keys x 512 cols (halfs, padded)
constexpr int SMEM_BYTES = BM * LDS * (int)sizeof(float) +
                           BM * LDS * (int)sizeof(__half) +
                           NWARPS * 256 * (int)sizeof(float) +
                           2 * KSTAGE * (int)sizeof(__half);
__device__ __forceinline__ void cp_async16(void* smem_dst, const void* gmem_src) {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
  unsigned saddr = (unsigned)__cvta_generic_to_shared(smem_dst);
  asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" :: "r"(saddr), "l"(gmem_src));
#else
  *reinterpret_cast<float4*>(smem_dst) = *reinterpret_cast<const float4*>(gmem_src);
#endif
}
__device__ __forceinline__ void cp_async_commit() {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
  asm volatile("cp.async.commit_group;\n");
#endif
}
template <int N>
__device__ __forceinline__ void cp_async_wait() {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
  asm volatile("cp.async.wait_group %0;\n" :: "n"(N));
#endif
}
__global__ void __launch_bounds__(256, 2) sdpa_kernel(const __half* __restrict__ Q,
                            const __half* __restrict__ K,
                            const __half* __restrict__ V,
                            __half* __restrict__ O,
                            int S, int D, float scale)
{
  const int tid  = threadIdx.x;
  const int lane = tid & 31;
  const int warp = tid >> 5;
  const int q0   = blockIdx.x * BM;
  const size_t bh = (size_t)blockIdx.y;
  const size_t base = bh * (size_t)S * (size_t)D;
  extern __shared__ char smem_raw[];
  __half* sP = reinterpret_cast<__half*>(smem_raw);            // [16,256] padded stride LDS
  float*  sS = reinterpret_cast<float*>(sP + BM * LDS);        // [16,256] padded stride LDS
  float*  sC = reinterpret_cast<float*>(sS + BM * LDS);        // [8][16,16] convert scratch
  __half* sK = reinterpret_cast<__half*>(sC + NWARPS * 256);   // staged K slabs 0,1 (slab 2 aliases sC)
  const __half* Qg = Q + base + (size_t)q0 * D;
  const __half* Kg = K + base;
  const __half* Vg = V + base;
  __half*       Og = O + base + (size_t)q0 * D;
  // Q fragments are loaded straight from global memory by the WMMA loads below
  // (L1-cached); dropping the sQ staging tile lets two CTAs reside per SM.
  // QK^T: 8 warps cover 16 key tiles of 16; each warp owns key tiles warp and warp+8.
  // K tiles are staged through shared memory with a 3-stage cp.async pipeline (the
  // third stage aliases the dead sC scratch) so global loads for depth step kt+32
  // overlap the tensor-core work of step kt and only one barrier is needed per step.
  #pragma unroll
  for (int rep = 0; rep < 2; ++rep) {
    const int nt = warp + rep * NWARPS;  // 16 key tiles total
    wmma::fragment<wmma::accumulator, 16, 16, 16, float> acc;
    wmma::fill_fragment(acc, 0.0f);
    {  // prologue: stage depth steps 0 and 1 into slabs 0 and 1
      const int row = tid >> 1;
      const int ch  = (tid & 1) * 8;
      #pragma unroll
      for (int p = 0; p < 2; ++p) {
        cp_async16(sK + p * KSTAGE + row * KLD + ch,
                   Kg + (size_t)(rep * 128 + row) * D + p * 16 + ch);
        cp_async_commit();
      }
    }
    #pragma unroll
    for (int kt = 0, it = 0; kt < BD; kt += 16, ++it) {
      cp_async_wait<1>();  // depth step kt has landed; two groups may stay in flight
      __syncthreads();
      {  // prefetch depth step it+2 into slab (it+2)%3; clamped at the tail (data unused)
        const int step = it + 2;
        const int d    = (step * 16 < BD) ? step * 16 : (BD - 16);
        __half* kdst   = (step % 3 == 2) ? reinterpret_cast<__half*>(sC)
                                         : (sK + (step % 3) * KSTAGE);
        const int row = tid >> 1;
        const int ch  = (tid & 1) * 8;
        cp_async16(kdst + row * KLD + ch,
                   Kg + (size_t)(rep * 128 + row) * D + d + ch);
        cp_async_commit();
      }
      const __half* ksrc = (it % 3 == 2) ? reinterpret_cast<const __half*>(sC)
                                         : (sK + (it % 3) * KSTAGE);
      wmma::fragment<wmma::matrix_a, 16, 16, 16, __half, wmma::row_major> a;
      wmma::fragment<wmma::matrix_b, 16, 16, 16, __half, wmma::col_major> b;
      wmma::load_matrix_sync(a, Qg + kt, D);
      wmma::load_matrix_sync(b, ksrc + warp * 16 * KLD, KLD);
      wmma::mma_sync(acc, a, b, acc);
    }
    cp_async_wait<0>();  // drain the pipeline before the next rep reuses the slabs
    __syncthreads();
    wmma::store_matrix_sync(sS + nt * 16, acc, LDS, wmma::mem_row_major);
  }
  __syncthreads();
  // Row softmax: 8 warps handle rows warp and warp+8; each warp reduces 256 columns.
  #pragma unroll
  for (int rep = 0; rep < 2; ++rep) {
    const int r = warp + rep * NWARPS;
    float xs[8];
    float mx = -INFINITY;
    #pragma unroll
    for (int i = 0; i < 8; ++i) {
      const int c = lane + i * 32;
      xs[i] = sS[r * LDS + c] * scale;
      mx = fmaxf(mx, xs[i]);
    }
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) mx = fmaxf(mx, __shfl_xor_sync(0xffffffffu, mx, off));
    float su = 0.0f;
    #pragma unroll
    for (int i = 0; i < 8; ++i) {
      xs[i] = expf(xs[i] - mx);
      su += xs[i];
    }
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) su += __shfl_xor_sync(0xffffffffu, su, off);
    const float inv = 1.0f / su;
    #pragma unroll
    for (int i = 0; i < 8; ++i) {
      const int c = lane + i * 32;
      sP[r * LDS + c] = __float2half(xs[i] * inv);
    }
  }
  __syncthreads();
  // P V: stage each 16-key x 512-col V slab through shared memory (the sS..sK
  // region is dead after the softmax and fits two V slabs) with a 2-stage
  // cp.async pipeline, so the WMMA B operand comes from shared memory.
  constexpr int OTILES = BD / 16;      // 64
  constexpr int PERW = OTILES / NWARPS; // 8
  __half* sV = reinterpret_cast<__half*>(sS);  // [2][16,VLD] staged V slabs (span the dead sS..sK region)
  wmma::fragment<wmma::accumulator, 16, 16, 16, float> oacc[PERW];
  #pragma unroll
  for (int i = 0; i < PERW; ++i) wmma::fill_fragment(oacc[i], 0.0f);
  #pragma unroll
  for (int h = 0; h < 2; ++h) {
    {  // prologue: stage key step 0 of this column half into slab 0
      const int row = tid >> 4;
      const int c0  = (tid & 15) * 8;
      #pragma unroll
      for (int j = 0; j < 4; ++j) {
        cp_async16(sV + row * VLD + c0 + j * 128,
                   Vg + (size_t)row * D + h * 512 + c0 + j * 128);
      }
      cp_async_commit();
    }
    #pragma unroll
    for (int kt = 0, it = 0; kt < BQ; kt += 16, ++it) {
      cp_async_wait<0>();  // key step kt has landed
      __syncthreads();
      {  // prefetch key step it+1 into slab (it+1)&1; clamped at the tail (data unused)
        const int step = it + 1;
